package com.mahweb.mahyarnfc.omnishare.ble;
import java.io.*; import java.util.*;
public final class BleChunkCodec { private static final int HEADER=12,MAX_TOTAL=256,MAX_PAYLOAD=32768; private BleChunkCodec(){}
 public static List<byte[]> split(int transferTag,byte[]payload,int maxValueBytes){if(payload==null)payload=new byte[0];if(payload.length>MAX_PAYLOAD)throw new IllegalArgumentException("payload too large");int room=maxValueBytes-HEADER;if(room<1)throw new IllegalArgumentException("MTU payload too small");int total=Math.max(1,(payload.length+room-1)/room);if(total>MAX_TOTAL)throw new IllegalArgumentException("too many chunks");List<byte[]>out=new ArrayList<>();for(int seq=0;seq<total;seq++){int off=seq*room,n=Math.min(room,payload.length-off);try{ByteArrayOutputStream b=new ByteArrayOutputStream();DataOutputStream d=new DataOutputStream(b);d.writeInt(transferTag);d.writeShort(seq);d.writeShort(total);d.writeInt(payload.length);if(n>0)d.write(payload,off,n);out.add(b.toByteArray());}catch(IOException e){throw new IllegalStateException(e);}}return out;}
 public static byte[] join(List<byte[]>chunks)throws IOException{if(chunks==null||chunks.isEmpty())throw new IOException("no chunks");Map<Integer,byte[]>parts=new HashMap<>();int tag=0,total=-1,len=-1;for(byte[]c:chunks){DataInputStream d=new DataInputStream(new ByteArrayInputStream(c));int t=d.readInt(),seq=d.readUnsignedShort(),tot=d.readUnsignedShort(),l=d.readInt();if(total<0){tag=t;total=tot;len=l;}if(t!=tag||tot!=total||l!=len||total<1||total>MAX_TOTAL||seq>=total||len<0||len>MAX_PAYLOAD)throw new IOException("invalid chunk header");byte[]body=new byte[d.available()];d.readFully(body);byte[]prior=parts.putIfAbsent(seq,body);if(prior!=null&&!Arrays.equals(prior,body))throw new IOException("conflicting duplicate");}if(parts.size()!=total)throw new IOException("missing chunks");ByteArrayOutputStream o=new ByteArrayOutputStream();for(int i=0;i<total;i++)o.write(parts.get(i));byte[]r=o.toByteArray();if(r.length!=len)throw new IOException("length mismatch");return r;}
}
